import React from 'react';

function Achievements({ data, page = false }) {
  if (!data) return null;
  const assetUrl = (url) => {
    if (!url || !url.startsWith('/api/')) return url;
    const apiBase = process.env.REACT_APP_API_URL
      || (process.env.NODE_ENV === 'development' ? 'http://localhost:5001' : '');
    return `${apiBase}${url}`;
  };

  return (
    <section id="achievements" className={page ? "min-h-screen py-16 md:py-24 bg-white" : "py-4 md:py-5 bg-white"}>
      <div className="max-w-7xl mx-auto px-4">
        <div className="mb-3 md:mb-4">
          <h2 className="text-lg md:text-2xl font-bold text-gray-900">
            Achievements
          </h2>
        </div>

        <div className="grid gap-3 md:grid-cols-2">
          {data.map((achievement) => (
            <div
              key={achievement.id}
              className="flex items-center justify-between gap-3 border border-gray-200 rounded-xl p-4"
            >
              <div className="flex items-center gap-3 min-w-0">
                {achievement.image && /\.(pdf)$/i.test(achievement.image) ? (
                  <a href={assetUrl(achievement.image)} target="_blank" rel="noopener noreferrer" className="h-16 w-16 rounded-lg bg-gray-900 text-white text-[10px] flex items-center justify-center flex-shrink-0">PDF</a>
                ) : achievement.image ? (
                  <img src={assetUrl(achievement.image)} alt={achievement.title} className="h-16 w-16 rounded-lg object-cover flex-shrink-0" />
                ) : null}
                <div className="min-w-0">
                  <h3 className="text-sm md:text-base font-semibold text-gray-800">{achievement.title}</h3>
                  <p className="text-xs text-gray-500">{achievement.type || 'Achievement'} · {achievement.year}</p>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

export default Achievements;
